import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def load_json_file(file_path):
    """Load JSON data from a file."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, FileNotFoundError):
        return None

def parse_date(date_str):
    """Parse a date string in YYYY-MM-DD format, handling optional time."""
    if not date_str:
        return None
    try:
        # Handle dates that might have time component
        return datetime.strptime(date_str.split()[0], "%Y-%m-%d").date()
    except (ValueError, AttributeError):
        return None

def extract_facts_from_award(award, rule_id, facts_needed):
    """Extract required facts from a single award based on rule_id."""
    result = {}

    if rule_id == "usa.period_3y":
        # Extract performance start and end dates
        period = award.get("period_of_performance", {})

        # Performance start
        if "performance start" in facts_needed:
            start_date_str = period.get("start_date")
            if start_date_str:
                result["performance start"] = [start_date_str.split()[0], "usaspending_awards"]
            else:
                result["performance start"] = "ABSENT"

        # Performance end
        if "performance end" in facts_needed:
            end_date_str = period.get("end_date")
            if end_date_str:
                result["performance end"] = [end_date_str.split()[0], "usaspending_awards"]
            else:
                result["performance end"] = "ABSENT"

    elif rule_id == "usa.obligated_95":
        # Extract amount obligated and potential value
        if "amount obligated" in facts_needed:
            obligated = award.get("total_obligation")
            if obligated is not None:
                # Format as decimal string
                result["amount obligated"] = [f"{float(obligated):.2f}", "usaspending_awards"]
            else:
                result["amount obligated"] = "ABSENT"

        if "potential value" in facts_needed:
            potential = award.get("base_and_all_options")
            if potential is not None:
                result["potential value"] = [f"{float(potential):.2f}", "usaspending_awards"]
            else:
                result["potential value"] = "ABSENT"

    return result

def process_packet(packet_dir, manifest):
    """Process the packet directory and manifest to extract facts."""
    # Load the usaspending_awards data
    awards_file = Path(packet_dir) / "usaspending_awards.json"
    awards_data = load_json_file(awards_file)

    if not awards_data or not isinstance(awards_data, list):
        print(json.dumps({}))
        return

    # Create a mapping from generated_unique_award_id to award
    awards_by_id = {}
    for award in awards_data:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            awards_by_id[award_id] = award

    # Process each pair in the manifest
    results = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)

        if entity not in awards_by_id:
            # Award not found, mark all facts as ABSENT
            facts_needed = manifest["facts"][rule_id]
            results[pair] = {fact: "ABSENT" for fact in facts_needed}
            continue

        award = awards_by_id[entity]
        facts_needed = manifest["facts"][rule_id]

        # Extract facts for this award and rule
        facts = extract_facts_from_award(award, rule_id, facts_needed)

        # Check for any missing facts that should be ABSENT
        for fact_name in facts_needed:
            if fact_name not in facts:
                facts[fact_name] = "ABSENT"

        results[pair] = facts

    # Output results as JSON
    print(json.dumps(results, indent=2))

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_file = sys.argv[2]

    # Load manifest
    manifest = load_json_file(manifest_file)
    if not manifest:
        print(json.dumps({}))
        return

    process_packet(packet_dir, manifest)

if __name__ == "__main__":
    main()
