    except (ValueError, TypeError):
        return None

def extract_fact_from_award(award, fact_name, rule_id):
    """Extract a specific fact from an award based on the rule."""
    if rule_id == "usa.period_3y":
        if fact_name == "performance start":
            date_str = award.get("period_of_performance", {}).get("start_date")
            return date_str, "usaspending_awards"
        elif fact_name == "performance end":
            date_str = award.get("period_of_performance", {}).get("end_date")
            return date_str, "usaspending_awards"

    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            amount = award.get("total_obligation")
            if amount is not None:
                return str(amount), "usaspending_awards"
            return None, "usaspending_awards"
        elif fact_name == "potential value":
            amount = award.get("base_and_all_options")
            if amount is not None:
                return str(amount), "usaspending_awards"
            return None, "usaspending_awards"

    return None, None

def process_pair(packet_dir, pair, facts_list, awards_data):
    """Process a single pair (rule_id::entity)."""
    rule_id, entity = pair.split("::", 1)
    result = {}

    # Find the award with matching generated_unique_award_id
    award = None
    for a in awards_data:
        if a.get("generated_unique_award_id") == entity:
            award = a
            break

    if award is None:
        # Award not found, all facts are ABSENT
        for fact_name in facts_list:
            result[fact_name] = "ABSENT"
        return result

    # Collect values for each fact
    fact_values = {}
    for fact_name in facts_list:
        value, doc = extract_fact_from_award(award, fact_name, rule_id)
        if value is None:
            fact_values[fact_name] = "ABSENT"
        else:
            fact_values[fact_name] = [value, doc]

    # Check for conflicts (multiple awards with same ID shouldn't happen here)
    # But if there were, we'd need to handle it
    result = fact_values

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

