    # Process each pair
    output = {}
    for pair in manifest["pairs"]:
        rule_id = pair.split("::")[0]
        facts_list = manifest["facts"][rule_id]
        output[pair] = process_pair(packet_dir, pair, facts_list, awards_data)

    # Output as JSON
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
