import json
import os
import sys
from datetime import datetime, timedelta
from typing import Dict, List, Any, Optional, Union

def load_json_file(filepath: str) -> Any:
    """Load JSON data from a file."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_date(date_str: Optional[str]) -> Optional[datetime]:
    """Parse a date string in YYYY-MM-DD format."""
    if not date_str:
        return None
    try:
        return datetime.strptime(date_str, "%Y-%m-%d")
    except (ValueError, TypeError):
        return None

def extract_fact_value(award: Dict[str, Any], fact_name: str, rule_id: str) -> Dict[str, Union[str, None]]:
    """
    Extract the value for a given fact from an award.
    Returns a dict with 'value' and 'document' keys.
    """
    if rule_id == "usa.period_3y":
        if fact_name == "performance start":
            path = award.get("period_of_performance", {}).get("start_date")
            value = str(path) if path is not None else None
            return {"value": value, "document": "usaspending_awards"}
        elif fact_name == "performance end":
            path = award.get("period_of_performance", {}).get("end_date")
            value = str(path) if path is not None else None
            return {"value": value, "document": "usaspending_awards"}

    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            path = award.get("total_obligation")
            # Convert to string if numeric, keep None if null
            if path is None:
                value = None
            else:
                value = str(path)
            return {"value": value, "document": "usaspending_awards"}
        elif fact_name == "potential value":
            path = award.get("base_and_all_options")
            if path is None:
                value = None
            else:
                value = str(path)
            return {"value": value, "document": "usaspending_awards"}

    return {"value": None, "document": None}

def process_pair(
    pair: str,
    awards: List[Dict[str, Any]],
    facts: List[str],
    rule_id: str
) -> Dict[str, Union[str, List, Dict]]:
    """
    Process a single pair (rule_id::entity).
    Returns a dict mapping each fact name to its result.
    """
    entity = pair.split("::")[1]

    # Find all awards matching the entity (generated_unique_award_id)
    matching_awards = [a for a in awards if a.get("generated_unique_award_id") == entity]

    if not matching_awards:
        # No matching award found
        return {fact: "ABSENT" for fact in facts}

    results = {}
    for fact_name in facts:
        # Collect values from all matching awards
        values = []
        for award in matching_awards:
            extracted = extract_fact_value(award, fact_name, rule_id)
            if extracted["value"] is not None:
                values.append((extracted["value"], extracted["document"]))

        if not values:
            results[fact_name] = "ABSENT"
        else:
            # Check for conflicts
            unique_values = set(v[0] for v in values)
            if len(unique_values) > 1:
                results[fact_name] = "CONFLICT"
            else:
                # All values agree, use the first one
                value, document = values[0]
                results[fact_name] = [value, document]

    return results

def main(packet_dir: str, manifest_path: str) -> None:
    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_by_rule = manifest["facts"]

    # Load awards data
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards = load_json_file(awards_file)

    # Process each pair
    output = {}
    for pair in pairs:
        rule_id, entity = pair.split("::")
        facts = facts_by_rule[rule_id]
        output[pair] = process_pair(pair, awards, facts, rule_id)

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]
    main(packet_dir, manifest_path)
