            amount = award.get("total_obligation")
            if amount is not None:
                # Ensure it's a decimal string
                return str(amount)
            return None
        elif fact_name == "potential value":
            # From base_and_all_options
            value = award.get("base_and_all_options")
            if value is not None:
                return str(value)
            return None
    return None

def process_packet(packet_dir, manifest):
