import json
import os
import sys
from datetime import datetime, timedelta
from typing import Dict, Any, List, Union

def load_json_file(filepath: str) -> Any:
    """Load JSON data from a file."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_date(date_str: str) -> datetime:
    """Parse a date string in YYYY-MM-DD format."""
    return datetime.strptime(date_str, "%Y-%m-%d")

def extract_fact_value(award: Dict[str, Any], fact_name: str) -> Union[str, None]:
    """Extract the value for a specific fact from an award record."""
    if fact_name == "performance start":
        start_date = award.get("period_of_performance", {}).get("start_date")
        return start_date if start_date else None
    elif fact_name == "performance end":
        end_date = award.get("period_of_performance", {}).get("end_date")
        return end_date if end_date else None
    elif fact_name == "amount obligated":
        obligated = award.get("total_obligation")
        # Handle null/None values
        if obligated is None:
            return None
        # Convert to string with proper decimal representation
        if isinstance(obligated, (int, float)):
            # Format without scientific notation, strip trailing zeros after decimal
            return format(obligated, 'f').rstrip('0').rstrip('.')
        return str(obligated)
    elif fact_name == "potential value":
        potential = award.get("base_and_all_options")
        if potential is None:
            return None
        if isinstance(potential, (int, float)):
            return format(potential, 'f').rstrip('0').rstrip('.')
        return str(potential)
    return None

def process_packet(packet_dir: str, manifest_path: str) -> Dict[str, Any]:
    """Process the packet and manifest to extract required facts."""
    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load awards data
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards_data = load_json_file(awards_file)

    # Create a mapping from generated_unique_award_id to award
    awards_by_id = {award["generated_unique_award_id"]: award for award in awards_data}

    # Initialize result structure
    result = {}

    # Process each pair
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)

        if entity not in awards_by_id:
            # Entity not found in awards data
            fact_names = manifest["facts"][rule_id]
            result[pair] = {fact: "ABSENT" for fact in fact_names}
            continue

        award = awards_by_id[entity]
        fact_names = manifest["facts"][rule_id]
        fact_values = {}

        for fact_name in fact_names:
            value = extract_fact_value(award, fact_name)

            if value is None:
                fact_values[fact_name] = "ABSENT"
            else:
                # For dates, ensure they're in YYYY-MM-DD format
                if fact_name in ["performance start", "performance end"]:
                    try:
                        # Validate date format
                        datetime.strptime(value, "%Y-%m-%d")
                    except ValueError:
                        fact_values[fact_name] = "ABSENT"
                        continue

                # Document name is always usaspending_awards (without extension)
                fact_values[fact_name] = [value, "usaspending_awards"]

        result[pair] = fact_values

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    try:
        result = process_packet(packet_dir, manifest_path)
        print(json.dumps(result, indent=2))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
